def decimal_to_binary(decimal: int) -> str:
    if decimal < 0:
        raise ValueError("Input must be a non-negative integer")

    binary_string = bin(decimal)[2:]  # Convert to binary and remove the '0b' prefix
    return f"db{binary_string}db"

